import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"贡献代码","description":"功能分支 PR：Conventional Commits 标题、必须绑定 Issue、自动版本号与更新日志、同步 OpenAPI、不要手改 generated。","frontmatter":{"title":"贡献代码","description":"功能分支 PR：Conventional Commits 标题、必须绑定 Issue、自动版本号与更新日志、同步 OpenAPI、不要手改 generated。"},"headers":[],"relativePath":"contribute/pull-requests.md","filePath":"contribute/pull-requests.md","lastUpdated":1790057721000}`),a={name:`contribute/pull-requests.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="贡献代码" tabindex="-1">贡献代码 <a class="header-anchor" href="#贡献代码" aria-label="Permalink to “贡献代码”">​</a></h1><p>从默认分支拉功能分支，向 <a href="https://github.com/Kirizu-Official/KiriVers" target="_blank" rel="noreferrer">https://github.com/Kirizu-Official/KiriVers</a> 开 PR。</p><h2 id="pr-标题就是版本号来源" tabindex="-1">PR 标题就是版本号来源 <a class="header-anchor" href="#pr-标题就是版本号来源" aria-label="Permalink to “PR 标题就是版本号来源”">​</a></h2><p>合入 <code>main</code> 的 squash 提交信息取自 PR 标题，而标题决定这次合入是否升版本：</p><table tabindex="0"><thead><tr><th>类型</th><th>档位</th></tr></thead><tbody><tr><td><code>feat</code></td><td>minor</td></tr><tr><td><code>fix</code> / <code>perf</code> / <code>revert</code></td><td>patch</td></tr><tr><td><code>type!:</code> 或正文 <code>BREAKING CHANGE:</code></td><td>major</td></tr><tr><td><code>docs</code> / <code>refactor</code> / <code>test</code> / <code>style</code> / <code>chore</code> / <code>ci</code> / <code>build</code></td><td>不发版</td></tr></tbody></table><p>写法：<code>&lt;类型&gt;(&lt;可选 scope&gt;): &lt;一句话说明&gt;</code>，例如 <code>fix(client): 修正空响应</code>。可用类型：feat | fix | perf | revert | docs | refactor | test | style | chore | ci | build。</p><ul><li><strong>scope 用小写</strong>（<code>perf(db)</code>，不是 <code>perf(DB)</code>）。它同时是更新日志里条目的归属标注。</li><li>破坏性变更写成 <code>类型!:</code> 或在正文加 <code>BREAKING CHANGE:</code> 脚注。</li><li>PR 标题与每个提交都要合规（<code>python3 dev/build/kirivers.py commitlint</code>）。不合规的 squash 标题会使检查失败。</li></ul><h2 id="pr-必须绑定-issue" tabindex="-1">PR 必须绑定 Issue <a class="header-anchor" href="#pr-必须绑定-issue" aria-label="Permalink to “PR 必须绑定 Issue”">​</a></h2><p>每个进 <code>main</code> 的 Pull Request 都要关联一个 Issue，两种方式任选：</p><ul><li>用右侧栏 <strong>Development → Link an issue</strong>，或</li><li>在 PR 描述里写一行 <code>Fixes #&lt;编号&gt;</code>（<code>Closes</code> / <code>Resolves</code> 同样有效，任意大小写）。</li></ul><p>确实不需要 Issue 时，给这个 PR 加 <code>skip-issue-check</code> 标签。</p><p>范围说明：<strong>只卡 <code>main</code> 的 PR</strong>。直推 <code>main</code>（维护者）与 <code>sdk/&lt;语言&gt;</code> 分支的 PR 不受这道门约束——SDK 分支的发版由该分支自己的流水线负责。</p><h3 id="守卫-bot-会做什么" tabindex="-1">守卫 bot 会做什么 <a class="header-anchor" href="#守卫-bot-会做什么" aria-label="Permalink to “守卫 bot 会做什么”">​</a></h3><p><code>.github/workflows/pr-guard.yml</code> 在 PR 打开、改标题、推新提交、重开、从 draft 转为可评审（ready for review）时复检标题格式与 Issue 关联，并在 PR 里维护<strong>一条</strong>留言（不会重复刷屏）：</p><ul><li>外部贡献者（非组织成员）未通过检查 → 留言并<strong>自动关闭</strong> PR。处理完之后点 <strong>Reopen pull request</strong> 重新打开即可，守卫会自动复检并把那条留言更新为通过提示；不必重开一个新的 PR。</li><li>组织成员（OWNER / MEMBER / COLLABORATOR）未通过 → 只留言提醒，不关闭。</li><li><strong>draft PR 与 bot 账号完全豁免</strong>（还没写完的东西不该被关）。</li></ul><p>守卫只读 PR 元数据，不检出、不执行 PR 带进来的任何代码，也不构建或测试。</p><p>先开 Issue 再开 PR 的顺序见 <a href="/contribute/bugs">报告缺陷</a>。</p><h2 id="更新日志自动生成-不要手写" tabindex="-1">更新日志自动生成，不要手写 <a class="header-anchor" href="#更新日志自动生成-不要手写" aria-label="Permalink to “更新日志自动生成，不要手写”">​</a></h2><p><code>CHANGELOG.md</code> 与 GitHub Release 正文都由发版脚本从 commit 生成（格式与可自定义的 emoji/文案见 <a href="/contribute/release#changelog-format">发版与 Docker</a>）。手工编辑 <code>CHANGELOG.md</code> 会在下一次发版被覆盖式插入挤乱，且不会带来版本号变化。章节由 <code>type</code> 决定、条目里的 <code>**scope**</code> 由你的 scope 决定——把 scope 写对，日志就自动归位。</p><h2 id="其他要求" tabindex="-1">其他要求 <a class="header-anchor" href="#其他要求" aria-label="Permalink to “其他要求”">​</a></h2><ul><li>相关 <code>go test</code> / 前端 lint 通过。</li><li>改 API 时同步该平面 <code>internal/controller/openapi.*.json</code>，并跑 <code>TestOpenAPIRoutesSync</code> 与 <code>TestPlaneSpecsValid</code>。</li><li>改前端契约后在 <code>frontend/</code> 执行 <code>yarn generate:api</code>。不要手改 <code>src/api/generated/</code> 或 <code>generated-client/</code>。</li><li>不要把各语言 SDK 源码推进 <code>main</code>（它们在孤儿分支 <code>sdk/&lt;语言&gt;</code> 上，见 <a href="/contribute/sdk">客户端 SDK</a>）。</li><li>不要提交带密钥的 <code>configs/*.yaml</code>（只用 <code>*-example.yaml</code>）。</li><li>合入 <code>main</code> <strong>不会</strong>触发服务端发布：发版是维护者手动运行的工作流。</li></ul><h2 id="本地自测" tabindex="-1">本地自测 <a class="header-anchor" href="#本地自测" aria-label="Permalink to “本地自测”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev/build/kirivers.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-workflows</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">      # 流水线静态门</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev/build/kirivers.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> guard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --self-check</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">   # 守卫判定矩阵</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev/build/kirivers.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> issue-link</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --self-check</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CGO_ENABLED</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Windows 上把 <code>python3</code> 换成 <code>python</code>。</p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};